<script setup>
import { onMounted,reactive,ref } from 'vue'
import { api,errorText } from '../state'
const cfg=reactive({}),busy=ref(false),error=ref(''),notice=ref('')
const groups=[
{title:'注册准入',fields:[['registration_review','开启注册审核','bool'],['registration_paid','开启注册付费','bool'],['registration_fee','注册费用（元）','money']]},
{title:'商品与域名',fields:[['blocked_keywords','商品屏蔽关键词（每行一个）','list'],['blocked_message','商品被屏蔽时显示内容','text'],['domain_add','允许商户申请授权支付域名','bool'],['domain_enforce','禁止未授权支付域名下单','bool']]},
{title:'手续费与退款',fields:[['fee_rate','平台服务费率（%）','money'],['fee_threshold','手续费低于此金额时触发最低扣除（元）','money'],['fee_minimum','最低扣除金额（元）','money'],['merchant_refund','开启商户后台自助退款','bool'],['refund_fee_payer','退款服务费承担方','select',[['platform','平台承担，按比例返还服务费'],['merchant','商户承担，服务费不退']]]]},
{title:'邀请返现',fields:[['invite_enabled','开启邀请返现','bool'],['invite_basis','邀请分成计算基数','select',[['fee','平台服务费'],['amount','订单金额']]],['invite_rate','邀请分成比例（%）','money'],['invite_cap_fee','返现不能超过订单服务费','bool'],['invite_timing','邀请返现释放时机','select',[['immediate','支付成功后'],['daily','次日零点后'],['settlement','订单转为可结算后']]]]},
{title:'商户保证金',fields:[['deposit_enabled','开启商户保证金门槛','bool'],['deposit_minimum','保证金最低充值金额（元）','money'],['deposit_freeze_days','保证金最少冻结天数','number']]},
{title:'支付风控',fields:[['risk_enabled','启用支付风控检查','bool'],['risk_window_seconds','统计窗口（秒）','number'],['risk_merchant_count','窗口内商户最多请求数','number'],['risk_ip_count','窗口内同 IP 最多请求数','number'],['risk_daily_amount','商户每日下单限额（元，0 不限制）','money'],['risk_failure_count','成功率检查最少已过期订单数','number'],['risk_min_success_rate','低于此支付成功率时暂停收款（%）','money'],['risk_callback_failures','连续回调失败订单数上限','number'],['blocked_ips','屏蔽 IP / CIDR（每行一个）','list']]},
{title:'结算规则',fields:[['settlement_mode','结算申请方式','select',[['off','关闭'],['manual','手动申请'],['auto','自动生成申请'],['both','手动与自动']]],['settlement_days','资金可结算等待天数（0 / 1 为 D+0 / D+1）','number'],['settlement_minimum','最低结算金额（元）','money'],['settlement_rate','结算手续费（%）','money'],['settlement_fee_min','结算手续费最小（元）','money'],['settlement_fee_max','结算手续费最大（元，0 不限制）','money'],['settlement_daily_limit','每日最多结算申请次数','number']]},
{title:'用户 IP 来源',fields:[['ip_source','读取方式','select',[['remote','直接连接 REMOTE_ADDR'],['x_real_ip','可信代理 X-Real-IP'],['x_forwarded_for','可信代理 X-Forwarded-For'],['cf_connecting_ip','可信代理 CF-Connecting-IP']]],['trusted_proxies','可信代理 IP / CIDR（每行一个）','list']]},
{title:'计划任务',fields:[['jobs_interval_seconds','平台任务轮询间隔（秒）','number'],['jobs_mail','启用邮件投递任务','bool'],['jobs_risk','启用风控巡检任务','bool'],['jobs_settlement','启用结算准备任务','bool'],['jobs_invite','启用邀请分成释放任务','bool']]},
]
async function load(){try{Object.assign(cfg,await api('/api/admin/policy'));for(const group of groups)for(const field of group.fields)if(field[2]==='list')cfg[field[0]]=cfg[field[0]].join('\n')}catch(e){error.value=errorText(e)}}
async function save(){busy.value=true;error.value='';notice.value='';try{const payload={...cfg};for(const group of groups)for(const field of group.fields){if(field[2]==='list')payload[field[0]]=String(cfg[field[0]]||'').split('\n').map(v=>v.trim()).filter(Boolean)}const result=await api('/api/admin/policy',{method:'PUT',body:JSON.stringify(payload)});cfg.version=result.version;notice.value='平台规则已保存，新订单使用新规则'}catch(e){error.value=errorText(e);if(e.message.startsWith('invalid_policy:'))error.value='请检查字段 '+e.message.split(':')[1]}finally{busy.value=false}}
onMounted(load)
</script>
<template><form class="operation-settings" @submit.prevent="save"><div class="policy-save-bar"><span class="field-hint">新费用规则对新订单生效，已有订单保留原规则</span><button class="button" :disabled="busy">{{ busy?'保存中':'保存平台规则' }}</button></div><p v-if="error" class="error-box" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><section v-for="group in groups" :key="group.title" class="hig-card settings-card"><h3>{{ group.title }}</h3><div class="policy-form-grid"><label v-for="field in group.fields" :key="field[0]" :class="{'check-field':field[2]==='bool','wide-field':field[2]==='list'}"><template v-if="field[2]==='bool'"><input type="checkbox" v-model="cfg[field[0]]" :disabled="busy"/>{{ field[1] }}</template><template v-else>{{ field[1] }}<select v-if="field[2]==='select'" v-model="cfg[field[0]]" :disabled="busy"><option v-for="item in field[3]" :key="item[0]" :value="item[0]">{{ item[1] }}</option></select><textarea v-else-if="field[2]==='list'" v-model="cfg[field[0]]" rows="3" :disabled="busy"/><input v-else-if="field[2]==='number'" type="number" min="0" step="1" v-model.number="cfg[field[0]]" :disabled="busy" required/><input v-else v-model="cfg[field[0]]" :inputmode="field[2]==='money'?'decimal':'text'" :disabled="busy" required/></template></label></div><p v-if="group.title==='结算规则'" class="field-hint">按北京时间日历日准备结算，自动任务只生成申请，管理员完成实际转账后登记凭据</p><p v-if="group.title==='商户保证金'" class="field-hint">通过已核验的支付充值，冻结到期且无未决交易后可转为可用余额</p></section></form></template>
